package com.tms.dispatch.controller;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.tms.common.R; import com.tms.order.entity.TransportOrder; import com.tms.order.mapper.TransportOrderMapper; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/dispatch") @RequiredArgsConstructor
public class DispatchController { private final TransportOrderMapper mapper; @GetMapping("/pending-orders") public R<List<TransportOrder>> pending(@RequestParam(required=false)String fromSiteCode){QueryWrapper<TransportOrder>q=new QueryWrapper<TransportOrder>().eq("status","CREATED");if(fromSiteCode!=null&&!fromSiteCode.isEmpty())q.eq("from_site_code",fromSiteCode);q.orderByDesc("priority");return R.ok(mapper.selectList(q));} }
